import React, { useState, useEffect } from 'react';
import { supabase } from '../servicios/supabase'; // Ajusta la ruta si es necesario
import '../estilos/escritorio/buscador.css';
import '../estilos/movil/buscador-responsivo.css';

const Inicio = ({ onSeleccionarSucursal }) => {
    const [sucursales, setSucursales] = useState([]);
    const [cargando, setCargando] = useState(true);

    useEffect(() => {
        const cargarSucursales = async () => {
            try {
                // Obtenemos las sucursales ordenadas por el mejor ranking
                const { data, error } = await supabase
                    .from('sucursales')
                    .select('*')
                    .order('ranking', { ascending: false });

                if (error) throw error;
                setSucursales(data);
            } catch (error) {
                console.error("Error cargando sucursales:", error.message);
            } finally {
                setCargando(false);
            }
        };

        cargarSucursales();
    }, []);

    return (
        <div className="contenedor-inicio">
            <header className="cabecera-principal">
                <h1>Terminal de Buses Bolivia</h1>
                <p>Selecciona una empresa para ver sus salidas específicas</p>
            </header>

            {cargando ? (
                <div className="estado-carga">Cargando empresas de transporte...</div>
            ) : (
                <div className="matriz-sucursales">
                    {sucursales.map((sucursal) => (
                        <div
                            key={sucursal.id}
                            className="tarjeta-sucursal"
                            onClick={() => onSeleccionarSucursal(sucursal.id)}
                        >
                            <div className="logo-contenedor">
                                {sucursal.logo_url ? (
                                    <img src={sucursal.logo_url} alt={`Logo ${sucursal.nombre}`} />
                                ) : (
                                    <div className="logo-placeholder">{sucursal.nombre.charAt(0)}</div>
                                )}
                            </div>
                            <h3 className="sucursal-nombre">{sucursal.nombre}</h3>
                            <div className="sucursal-ranking">
                                ⭐ {sucursal.ranking ? sucursal.ranking.toFixed(1) : 'S/N'}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

export default Inicio;
